{
  "avaliacoes": [
    {
      "id": "Efaf8e11877d0b18a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A formação de emulsão água-em-óleo durante a produção é associada ao cisalhamento turbulento em dutos, bombas e até à movimentação de fluidos no reservatório, conectando o histórico de escoamento à carga de emulsão que chega ao tratador.",
          "trechos": [
            "Efaf8e11877d0b18a:1397:2092"
          ],
          "condicoes": [
            "durante a produção de petróleo",
            "na presença de cisalhamento turbulento no sistema"
          ],
          "limites": [
            "a fonte não quantifica intensidade de cisalhamento nem compara equipamentos",
            "não trata diretamente de desempenho em FPSO específico"
          ]
        },
        {
          "proposicao": "O tamanho das gotas de água em emulsão é apresentado como dependente de tensão interfacial, taxa de cisalhamento, natureza dos agentes emulsificantes, presença de sólidos e propriedades do óleo e da água, relacionando viscosidade, composição interfacial e sólidos à dificuldade de separação.",
          "trechos": [
            "Efaf8e11877d0b18a:2092:2486"
          ],
          "condicoes": [
            "para emulsões água-em-óleo no contexto de produção"
          ],
          "limites": [
            "a fonte não isola a contribuição individual de viscosidade, densidade, salinidade ou sólidos",
            "não fornece critérios quantitativos de seleção ou ajuste operacional"
          ]
        },
        {
          "proposicao": "A quebra da emulsão é descrita como um processo de coalescência que gera gotas maiores, as quais tendem a se segregar, oferecendo a base mecânica para entender por que a promoção de coalescência melhora a separação no tratador.",
          "trechos": [
            "Efaf8e11877d0b18a:2092:2486"
          ],
          "condicoes": [
            "quando ocorre crescimento de gotas por coalescência"
          ],
          "limites": [
            "a fonte não detalha, nesse trecho, como campo elétrico, eletrodos ou tensão modificam essa coalescência",
            "não informa tempos de residência nem faixas operacionais"
          ]
        }
      ]
    },
    {
      "id": "E58f48c5a813d35ab",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Mesmo com remoção total das gotas presentes no petróleo, a fonte afirma que permanece água residual dissolvida molecularmente; assim, retirar apenas a fase dispersa não implica eliminação completa do teor de água no óleo.",
          "trechos": [
            "E58f48c5a813d35ab:0:699"
          ],
          "condicoes": [
            "sob aumento da solubilidade da água no petróleo com a temperatura",
            "mesmo após remoção das gotas de água dispersa"
          ],
          "limites": [
            "a fonte não quantifica a fração dissolvida remanescente",
            "não estabelece especificações numéricas porque os valores estão apagados"
          ]
        },
        {
          "proposicao": "O tratador Dual Frequency é descrito como usando controle de frequência variável para modular o campo elétrico conforme propriedades físicas do óleo produzido, o que liga características do fluido ao ajuste do campo.",
          "trechos": [
            "E58f48c5a813d35ab:0:699"
          ],
          "condicoes": [
            "na descrição do princípio operacional do equipamento Dual Frequency"
          ],
          "limites": [
            "a fonte não explicita, nesse trecho, quais propriedades físicas governam cada ajuste",
            "não apresenta algoritmo, faixa de frequência ou lógica de controle"
          ]
        },
        {
          "proposicao": "Segundo a própria fonte, resultados de testes laboratoriais e de campo indicam que tensão e frequência variáveis permitem otimizar a desidratação mesmo com fluxo de óleo significativamente maior para mesmas dimensões do vaso.",
          "trechos": [
            "E58f48c5a813d35ab:1392:2086",
            "E58f48c5a813d35ab:2086:2272"
          ],
          "condicoes": [
            "nos testes laboratoriais e de campo mencionados",
            "para diferentes tipos de petróleo"
          ],
          "limites": [
            "os dados numéricos e condições detalhadas dos testes não estão disponíveis integralmente no trecho",
            "o resultado experimental não deve ser generalizado como superioridade universal para qualquer óleo ou instalação"
          ]
        }
      ]
    },
    {
      "id": "E3829ddfc75b59aa4",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": []
    },
    {
      "id": "E1b068211458289fc",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Após a separação do gás, o óleo ainda pode apresentar água e sedimentos acima dos valores de exportação, e sua desestabilização é descrita como feita por combinação de calor, campo elétrico e desemulsificante.",
          "trechos": [
            "E1b068211458289fc:0:698",
            "E1b068211458289fc:698:1393"
          ],
          "condicoes": [
            "após a etapa de separação do gás",
            "quando o óleo ainda contém água livre e emulsionada"
          ],
          "limites": [
            "os valores numéricos de especificação aparecem apagados",
            "a fonte não detalha critérios de seleção entre calor, químico e campo elétrico"
          ]
        },
        {
          "proposicao": "A fonte recomenda que o desemulsificante seja aplicado o mais cedo possível, e atribui à combinação de calor, campo elétrico e químico o enfraquecimento da película ao redor das gotas, favorecendo coalescência e sedimentação gravitacional.",
          "trechos": [
            "E1b068211458289fc:698:1393"
          ],
          "condicoes": [
            "quando há água emulsionada no petróleo"
          ],
          "limites": [
            "não há formulação, dosagem, ponto exato de injeção nem compatibilidade química detalhada",
            "trata-se de orientação técnica da fonte, não de regra universal"
          ]
        },
        {
          "proposicao": "A água produzida deve ser separada do petróleo o mais cedo possível no contexto offshore, e a fonte informa que a água oriunda de separadores e tratadores precisa de tratamento adicional para atendimento ambiental antes do descarte.",
          "trechos": [
            "E1b068211458289fc:698:1393",
            "E1b068211458289fc:1393:2091",
            "E1b068211458289fc:2091:2265"
          ],
          "condicoes": [
            "no contexto de unidades offshore",
            "quando a água produzida será descartada"
          ],
          "limites": [
            "o trecho normativo está com números apagados e não permite reconstruir limites",
            "a fonte não discute como esse requisito ambiental retroage diretamente sobre o ajuste interno do tratador eletrostático"
          ]
        }
      ]
    },
    {
      "id": "Eae53ae3e12ad24df",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte relaciona a presença de água, sais e sólidos a problemas ao longo da cadeia de produção, esclarecendo que os sais ficam normalmente dissolvidos na fase aquosa, mas também podem aparecer como cristais, o que afeta a estratégia de remoção.",
          "trechos": [
            "Eae53ae3e12ad24df:0:699"
          ],
          "condicoes": [
            "quando água salina e contaminantes sólidos acompanham o petróleo"
          ],
          "limites": [
            "não há quantificação do impacto operacional de cada contaminante",
            "não separa efeitos específicos sobre desempenho eletrostático, corrosão, incrustação ou especificação final"
          ]
        },
        {
          "proposicao": "Cristais de sais na fase oleosa só seriam removidos com lavagem adequada, e partículas sólidas molháveis pela água são descritas como mais fáceis de remover quando há bom contato com água de lavagem, conectando salinidade e sólidos à eficácia da etapa de lavagem.",
          "trechos": [
            "Eae53ae3e12ad24df:0:699"
          ],
          "condicoes": [
            "quando existem cristais de sais na fase oleosa",
            "quando as partículas sólidas são molháveis pela água",
            "havendo bom contato com a água de lavagem"
          ],
          "limites": [
            "a fonte não informa razão água/óleo, intensidade de mistura nem qualidade da água de lavagem",
            "não traz desempenho comparativo entre estratégias de lavagem"
          ]
        },
        {
          "proposicao": "Nas unidades de produção, separadores trifásicos removem água livre e gotas maiores por tempo de residência, e o óleo morto segue para desidratadores eletrostáticos, cujas placas energizadas promovem coalescência das gotas menores e aumentam sua taxa de sedimentação.",
          "trechos": [
            "Eae53ae3e12ad24df:699:1396"
          ],
          "condicoes": [
            "após remoção prévia de água livre em separadores trifásicos",
            "para gotas menores remanescentes dispersas no óleo"
          ],
          "limites": [
            "a fonte não fornece tempos de residência, geometrias de placas ou tensões aplicadas",
            "não aborda diretamente efeitos de gás livre, espuma ou curto-circuito"
          ]
        }
      ]
    },
    {
